pub fn i32x4ExtaddPairwiseI16x8S(value: V128) V128 {
    const PairT = i32;
    const PairVec = @Vector(4, PairT);
    const pairs = vecFromV128(PairT, 4, value);
    const bits = @bitSizeOf(i16);
    const shift_amt: @Vector(4, std.math.Log2Int(PairT)) = @splat(bits);
    if (true) {
        const low: PairVec = (pairs << shift_amt) >> shift_amt;
        const high: PairVec = pairs >> shift_amt;
        return v128FromVec(PairT, 4, low + high);
    } else {
        const mask_val: PairT = (@as(PairT, 1) << @intCast(bits)) - 1;
        const mask: PairVec = @splat(mask_val);
        const low: PairVec = pairs & mask;
        const high: PairVec = pairs >> shift_amt;
        return v128FromVec(PairT, 4, low + high);
    }
}

