pub fn i64x2AllTrue(value: V128) bool {
    const lanes = vecFromV128(i64, 2, value);
    const zero: I64x2 = @splat(0);
    return @reduce(.And, lanes != zero);
}

pub fn i64x2Bitmask(value: V128) i32 {
    const lanes = vecFromV128(i64, 2, value);
    const zero: I64x2 = @splat(0);
    const sign_bits: @Vector(2, u1) = @bitCast(lanes < zero);
    const MaskInt = std.meta.Int(.unsigned, 2);
    const mask_uint: MaskInt = @bitCast(sign_bits);
    return @as(i32, @intCast(mask_uint));
}

pub fn i64x2Eq(lhs: V128, rhs: V128) V128 {
    const a = vecFromV128(i64, 2, lhs);
    const b = vecFromV128(i64, 2, rhs);
    const mask = a == b;
    return vectorMaskToV128(i64, 2, mask);
}

pub fn i64x2ExtendHighI32x4S(value: V128) V128 {
    var out = std.mem.zeroes([16]u8);
    inline for (0..2) |i| {
        const lane = readLane(i32, value.bytes, @intCast(2 + i));
        const result: i64 = if (true) @as(i64, lane) else @as(i64, @intCast(lane));
        writeLane(i64, &out, @intCast(i), result);
    }
    return v128FromBytes(out);
}

