        const a = readLane(i32, lhs.bytes, @intCast(2 + i));
        const b = readLane(i32, rhs.bytes, @intCast(2 + i));
        const result: i64 = @as(i64, a) * @as(i64, b);
        writeLane(i64, &out, @intCast(i), result);
