pub fn i64x2Shl(value: V128, amount: u32) V128 {
    const ShiftT = std.math.Log2Int(i64);
    const shift: ShiftT = @intCast(amount % @bitSizeOf(i64));
    const lanes = vecFromV128(i64, 2, value);
    const shifts: @Vector(2, ShiftT) = @splat(shift);
    return v128FromVec(i64, 2, lanes << shifts);
}

