pub fn i8x16Abs(value: V128) V128 {
    const lanes = vecFromV128(i8, 16, value);
    const zero: I8x16 = @splat(0);
    const results: I8x16 = @select(i8, lanes < zero, zero -% lanes, lanes);
    return v128FromVec(i8, 16, results);
}

