pub fn i8x16AvgrU(lhs: V128, rhs: V128) V128 {
    const a = vecFromV128(u8, 16, lhs);
    const b = vecFromV128(u8, 16, rhs);
    const ShiftT = std.math.Log2Int(u8);
    const shifts: @Vector(16, ShiftT) = @splat(1);
    return v128FromVec(u8, 16, (a | b) - ((a ^ b) >> shifts));
}

