pub fn i8x16NarrowI16x8S(lhs: V128, rhs: V128) V128 {
    var out = std.mem.zeroes([16]u8);
    inline for (0..8) |i| {
        writeLane(i8, &out, @intCast(i), narrowLane(i16, i8, readLane(i16, lhs.bytes, @intCast(i)), true));
        writeLane(i8, &out, @intCast(8 + i), narrowLane(i16, i8, readLane(i16, rhs.bytes, @intCast(i)), true));
    }
    return v128FromBytes(out);
}

